<?php require_once __DIR__.'/../includes/bootstrap.php';if(admin())redirect('/admin/index.php');$err='';if(is_post()){verify_csrf();$st=db()->prepare('SELECT * FROM users WHERE email=? AND role="admin" AND status=1');$st->execute([post('email')]);$u=$st->fetch();if($u&&password_verify((string)post('password'),$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'phone'=>$u['phone'],'role'=>$u['role']];redirect('/admin/index.php');}$err='Invalid admin credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com"></script><script src="https://code.iconify.design/3/3.1.0/iconify.min.js"></script></head><body class="min-h-screen grid place-items-center bg-slate-950"><div class="w-full max-w-sm p-6 bg-white rounded-3xl"><div class="font-black text-2xl">PAROKO Admin</div><p class="text-sm text-slate-500 mt-1">Secure admin login</p><?php if($err):?><div class="mt-4 p-3 rounded-xl bg-rose-50 text-rose-700"><?=e($err)?></div><?php endif;?><form method="post" class="mt-5 space-y-3"><?=csrf_input()?><input class="w-full rounded-xl border-slate-200" name="email" type="email" placeholder="Admin email" value="<?=DEMO_ADMIN_EMAIL?>"><input class="w-full rounded-xl border-slate-200" name="password" type="password" placeholder="Password"><button class="w-full rounded-xl bg-slate-950 text-white py-3 font-black">Login</button></form></div></body></html>
